begin;
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); extra uuid:=gen_random_uuid(); pickup uuid:=gen_random_uuid(); rival uuid:=gen_random_uuid(); receiver uuid:=gen_random_uuid(); result jsonb; s jsonb; job text:='AX-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));
begin
 perform public.axic_create_consignment(jsonb_build_object('id',job,'origin','Lagos','destination','Abuja','status','Booked','location','Lagos','events','[]'::jsonb),'{}','{}',jsonb_build_array(jsonb_build_object('id',a,'description','QA one','weight',1),jsonb_build_object('id',b,'description','QA two','weight',2)));
 if (select count(*) from public.axic_workflow_alerts where consignment_id=job and state='Lagos' and kind='Pickup available')<>1 then raise exception 'Missing origin notification';end if;
 begin perform public.axic_workflow_action(job,'claim_pickup',rival,'Wrong state','Kano');raise exception 'Wrong-state claim accepted';exception when insufficient_privilege then null;end;
 result:=public.axic_workflow_action(job,'claim_pickup',pickup,'Pickup staff','Lagos');
 if result->>'stage'<>'Pickup claimed' then raise exception 'Claim failed';end if;
 begin perform public.axic_workflow_action(job,'claim_pickup',rival,'Rival','Lagos');raise exception 'Competing claim accepted';exception when unique_violation then null;end;
 insert into public.axic_goods(id,description,weight) values(extra,'Loose',1);
 begin perform public.axic_assign_good(extra,job);raise exception 'Item set changed after claim';exception when unique_violation then null;end;
 begin perform public.axic_workflow_action(job,'scan_pickup',rival,'Rival','Lagos',a,gen_random_uuid());raise exception 'Non-owner scan accepted';exception when insufficient_privilege then null;end;
 begin perform public.axic_workflow_action(job,'dispatch',pickup,'Pickup staff','Lagos');raise exception 'Early dispatch accepted';exception when unique_violation then null;end;
 result:=public.axic_workflow_action(job,'scan_pickup',pickup,'Pickup staff','Lagos',a,gen_random_uuid());
 if result->>'stage'<>'Pickup claimed' then raise exception 'Partial pickup advanced';end if;
 perform public.axic_workflow_action(job,'scan_pickup',pickup,'Pickup staff','Lagos',a,gen_random_uuid());
 if (select count(*) from public.axic_workflow_scans where consignment_id=job)<>1 then raise exception 'Duplicate scan';end if;
 result:=public.axic_workflow_action(job,'scan_pickup',pickup,'Pickup staff','Lagos',b,gen_random_uuid());
 if result->>'stage'<>'Collected' then raise exception 'Collection incomplete';end if;
 select payload into s from public.axic_shipments where id=job;
 if s->>'status'<>'Collected' or jsonb_array_length(s->'events')<>2 then raise exception 'Collection milestone mismatch';end if;
 perform public.axic_workflow_action(job,'dispatch',pickup,'Pickup staff','Lagos');
 if (select count(*) from public.axic_workflow_alerts where consignment_id=job and state='Abuja')<>1 then raise exception 'Missing incoming alert';end if;
 perform public.axic_workflow_action(job,'claim_arrival',receiver,'Receiving staff','Abuja');
 begin perform public.axic_workflow_action(job,'claim_arrival',rival,'Rival','Abuja');raise exception 'Competing receipt accepted';exception when unique_violation then null;end;
 begin perform public.axic_workflow_action(job,'claim_delivery',receiver,'Receiving staff','Abuja');raise exception 'Early delivery accepted';exception when unique_violation then null;end;
 result:=public.axic_workflow_action(job,'scan_arrival',receiver,'Receiving staff','Abuja',a,gen_random_uuid());
 if result->>'stage'<>'Arrival claimed' then raise exception 'Partial arrival advanced';end if;
 result:=public.axic_workflow_action(job,'scan_arrival',receiver,'Receiving staff','Abuja',b,gen_random_uuid());
 if result->>'stage'<>'At destination' then raise exception 'Arrival completion failed';end if;
 begin perform public.axic_workflow_action(job,'claim_delivery',rival,'Rival','Abuja');raise exception 'Different receiver took delivery';exception when insufficient_privilege then null;end;
 perform public.axic_workflow_action(job,'claim_delivery',receiver,'Receiving staff','Abuja');
 result:=public.axic_workflow_action(job,'deliver',receiver,'Receiving staff','Abuja');
 if result->>'stage'<>'Delivered' then raise exception 'Delivery failed';end if;
 perform public.axic_workflow_action(job,'deliver',receiver,'Receiving staff','Abuja');
 select payload into s from public.axic_shipments where id=job;
 if s->>'status'<>'Delivered' or jsonb_array_length(s->'events')<>7 then raise exception 'Final milestone or duplicate check failed';end if;
 if (select count(*) from public.axic_workflow_scans where consignment_id=job)<>4 then raise exception 'Audit count mismatch';end if;
end $$;
select bool_and(relrowsecurity) as all_rls_enabled,bool_or(has_table_privilege('anon',oid,'SELECT')) as anonymous_read,bool_or(has_table_privilege('authenticated',oid,'INSERT')) as client_write from pg_class where relname in ('axic_workflows','axic_workflow_scans','axic_workflow_alerts','axic_workflow_reads');
select has_function_privilege('anon','public.axic_workflow_action(text,text,uuid,text,text,uuid,uuid)','EXECUTE') as anonymous_action;
rollback;
